rule_structure:
{
    "dc_to_store_strategy": {
        "label": "DC to Store Strategy",
        "value": {
            "label": "Choose Strategy",
            "type": "dropdown",
            "value": [
                {"mins_first_and_then_wos": "Mins First and then WOS"},
                {"mins_only": "Mins Only"},
                {"wos_only": "WOS only"}
            ]
        }
	}
}

{
	"demand_type": {
      "label": "Demand Type",
      "value": {
        "label": "Demand Type",
        "type": "dropdown",
        "value": [
          {
            "ia_forecast": "IA Forecast"
          },
          {
            "fixed_inventory_push": "Fixed Inventory Push"
          }
        ],
        "dependencies": [
          {
            "label": "IA Forecast",
            "value": {
              "type": "-"
            },
            "show_on": "ia_forecast",
            "default_value": "-"
          },
          {
            "label": "Fixed Inventory Push",
            "value": {
              "type": "percent"
            },
            "show_on": "fixed_inventory_push",
            "default_value": "10%",
            "min": 0,
            "max": 100
          }
        ]
      }
    }
}

{	
    "dc_inventory_source": {
        "label": "DC Inventory Source",
        "value": {
            "label": "Choose Source",
            "type": "dropdown",
            "value": [
                {"on_hand": "DC on hand"},
                {"on_hand_oo": "DC OH + OO"}
            ]
        }
    }
}
